#include <bits/stdc++.h>
#define int long long
using namespace std;

int mod = 1e6+3;

vector<int> fact(mod);

int inv(int a){
    return a <= 1 ? a : mod - mod / a * inv(mod % a) % mod;
}

void solve(){
    int n, x, ans = 1;
    cin >> n;
    vector<int> a(n), b(n);
    for(int i=0; i<n; i++)
        cin >> a[i];
    for(int i=0; i<n; i++)
        cin >> b[i];
    int k = __lg(b[0] / a[0]);
    for(int i=1; i<n; i++)
        k = min(k, __lg(b[i] / a[i]));
    x = k;
    vector<int> cnt(k), c(n);
    for(int i=0; i<n; i++){
        for(int j=0; j<k; j++){
            cnt[j] += b[i] & 1;
            b[i] >>= 1;
        }
        c[i] = b[i] - a[i];
    }
    for(int j=0; j<k; j++){
        x += cnt[j];
        ans = ans * fact[cnt[j]] % mod;
    }
    int last = accumulate(c.begin(), c.end(), 0LL);
    ans = (last < mod ? ans * fact[last] % mod : 0);
    for(int i : c){
        x += i;
        ans = ans * inv(fact[i]) % mod;
    }
    cout << x << ' ' << ans << '\n';
}

signed main(){
    ios::sync_with_stdio(false);
    cin.tie(NULL);
    fact[0] = 1;
    for(int i=1; i<mod; i++) fact[i] = fact[i-1] * i % mod;
    int t;
    cin >> t;
    while(t--) solve();
}

#include <bits/stdc++.h>
using namespace std;

void solve(){
    int n, m;
    cin >> n >> m;
    vector<int> mx(m-n+1);
    function<int(int)> query = [&](int i)->int{
        int ret = 0;
        for(; i>=0; i=(i&i+1)-1)
            ret = max(ret, mx[i]);
        return ret;
    };
    function<void(int, int)> update = [&](int i, int val){
        for(; i<=m-n; i|=i+1)
            mx[i] = max(mx[i], val);
    };
    function<int(int, int)> v = [](int b, int x)->int{
        int ans = 0;
        while(!(x % b)){
            ans++;
            x /= b;
        }
        return ans;
    };
    for(int i=2; i<=n; i++)
        for(int j=(m-n+i)/i*i; j>=i; j-=i)
            update(j-i, query(j-i) + v(i, j));
    cout << query(m-n) << '\n';
}

int main(){
    ios::sync_with_stdio(false);
    cin.tie(NULL);
    int t;
    cin >> t;
    while(t--) solve();
}
